function norm(value){return String(value??"").trim().normalize("NFD").replace(/[\u0300-\u036f]/g,"").toUpperCase().replace(/[^A-Z0-9]+/g," ").replace(/\s+/g," ").trim();}
function canonical(value){const n=norm(value);if(!n)return"";if(ALIASES.has(n))return ALIASES.get(n);if(n==="SANTIAGO DE CALI")return"CALI";if(n==="BUGA")return"GUADALAJARA DE BUGA";if(["CALIMA","EL DARIEN","CALIMA EL DARIEN"].includes(n))return"CALIMA EL DARIEN";return n;}
