function toNumber(value){if(value===null||value===undefined||String(value).trim()==="")return null;let s=String(value).trim().replace(/\$/g,"").replace(/\s/g,"");if(/^[-+]?\d{1,3}(\.\d{3})+(,\d+)?$/.test(s))s=s.replace(/\./g,"").replace(",",".");else if(/^[-+]?\d+(,\d+)$/.test(s))s=s.replace(",",".");const n=Number(s);return Number.isFinite(n)?n:null;}
function num(value){return toNumber(value)??0;}function fmt(value){const n=toNumber(value);return n===null?"Sin dato":Math.round(n).toLocaleString("es-CO");}function fmtPct(value){const n=toNumber(value);return n===null?"Sin dato":`${n.toLocaleString("es-CO",{maximumFractionDigits:1})} %`;}
function isLocal(){return["localhost","127.0.0.1","0.0.0.0"].includes(location.hostname);}
