function buildAliases(){ALIASES=new Map();DATA.homologacion.forEach(r=>{if(r.alias_clave&&r.municipio_clave)ALIASES.set(norm(r.alias_clave),norm(r.municipio_clave));});DATA.municipios.forEach(r=>{const key=canonical(r.municipio);ALIASES.set(norm(r.municipio),key);ALIASES.set(norm(r.municipio_normalizado),key);});}
