function regexEscape(value){return String(value??"").replace(/[.*+?^${}()|[\]\\]/g,"\\$&");}
function ensureLocalFilterStrip(tableId){const table=document.getElementById(tableId);if(!table)return null;let strip=document.getElementById(`${tableId}LocalFilter`);if(strip)return strip;strip=document.createElement("div");strip.id=`${tableId}LocalFilter`;strip.className="chart-filter-strip d-none";strip.innerHTML=`<div><strong>Filtro desde gráfico:</strong> <span data-filter-label></span></div><button class="btn btn-outline-secondary btn-sm" type="button">Limpiar</button>`;const wrapper=table.closest(".table-responsive");wrapper?.parentNode?.insertBefore(strip,wrapper);strip.querySelector("button")?.addEventListener("click",()=>clearLocalTableFilter(tableId));return strip;}
function clearLocalTableFilter(tableId){const t=tables[tableId];if(t){t.search("");t.columns().search("");t.draw();}const strip=document.getElementById(`${tableId}LocalFilter`);strip?.classList.add("d-none");document.querySelectorAll(`[data-filter-table="${tableId}"]`).forEach(el=>el.classList.remove("selected-filter"));}
