 const conditions=[["Agua","agua_afectada",2],["Salud","salud_afectada",3],["Energía","energia_afectada",4],["Accesibilidad","accesibilidad_afectada",6],["Albergue / refugio","albergue_reportado",5]];horizontalBar("chartContextConditions",conditions.map(x=>x[0]),conditions.map(x=>countTrue(context,x[1])),"Municipios","#0f766e",false,(i,label)=>{const c=conditions[i];if(c)setLocalTableFilter("tblContext",c[2],"Sí",`Condición: ${label}`,true,"chartContextConditions");});
 const alertFields=[["Agua + salud","alerta_agua_salud"],["Agua + albergue","alerta_agua_albergue"],["Agua + energía","alerta_agua_energia"],["Agua + acceso","alerta_agua_acceso"],["Albergue + energía","alerta_albergue_energia"]];horizontalBar("chartAlerts",alertFields.map(x=>x[0]),alertFields.map(x=>countTrue(context,x[1])),"Municipios","#dc2626",false,(i,label)=>setLocalTableFilter("tblContext",8,label,`Alerta: ${label}`,false,"chartAlerts"));
 const healthTotals=[["averiadas",sum(health,"averiadas")],["uso restringido",sum(health,"uso_restringido")],["fuera de servicio",sum(health,"fuera_servicio")],["destruidas",sum(health,"destruidas")]];const hs=document.getElementById("healthEdanSummary");if(hs)hs.innerHTML=`<strong>EDAN · instalaciones de salud:</strong> ${healthTotals.map(x=>`${fmt(x[1])} ${x[0]}`).join(" · ")}. Esta lectura se complementa abajo con 42 hospitales principales georreferenciados.`;
