function hospitalPct(r){return toNumber(r.afectacion_pct);}function hospitalColor(level){const n=norm(level);if(n.includes("COLAPSO"))return"#991b1b";if(n.includes("CRITICA"))return"#dc2626";if(n.includes("MUY ALTA"))return"#f97316";if(n==="ALTA")return"#fb923c";if(n.includes("MODERADA"))return"#facc15";if(n==="BAJA")return"#84cc16";if(n.includes("SIN AFECTACION"))return"#16a34a";return"#94a3b8";}
function renderHospitals(rows){document.getElementById("hospTotal").textContent=fmt(rows.length);document.getElementById("hospAffected").textContent=fmt(rows.filter(r=>(hospitalPct(r)||0)>0).length);document.getElementById("hospHigh").textContent=fmt(rows.filter(r=>(hospitalPct(r)||0)>=50).length);document.getElementById("hospCritical").textContent=fmt(rows.filter(r=>(hospitalPct(r)||0)>=70).length);const levels=new Map();rows.forEach(r=>levels.set(r.nivel_afectacion||"Sin nivel",(levels.get(r.nivel_afectacion||"Sin nivel")||0)+1));const ordered=[...levels.entries()].sort((a,b)=>b[1]-a[1]);horizontalBar("chartHospitalLevels",ordered.map(x=>x[0]),ordered.map(x=>x[1]),"Hospitales","#2563eb",false,(i,label)=>setLocalTableFilter("tblHospitals",4,label,`Nivel hospitalario: ${label}`,true,"chartHospitalLevels"));const top=rows.filter(r=>hospitalPct(r)!==null).sort((a,b)=>(hospitalPct(b)||0)-(hospitalPct(a)||0)).slice(0,10);horizontalBar("chartHospitalTop",top.map(r=>`${r.municipio} · ${r.institucion}`),top.map(r=>hospitalPct(r)||0),"%","#dc2626",true,(i)=>{const r=top[i];if(r)selectMunicipalityFromChart(r.municipio);});renderTable("tblHospitals",rows.map(r=>[r.municipio,r.aro_uesvalle||municipalityAro(r.municipio),r.institucion,hospitalPct(r)===null?"Sin porcentaje":fmtPct(r.afectacion_pct),r.nivel_afectacion,r.georef_estado,r.necesidades_prioritarias_fuente||""]),["MUNICIPIO","ARO","HOSPITAL","AFECTACIÓN","NIVEL","GEORREFERENCIACIÓN","REPORTE / NECESIDADES"],"EDAN_HOSPITALES");}
function municipalityAro(municipio){return DATA.municipios.find(m=>canonical(m.municipio)===canonical(municipio))?.aro_uesvalle||"";}
function renderTerritory(housing,territory){const top=[...housing].map(r=>[r.municipio,num(r.total_averiadas)]).filter(x=>x[1]>0).sort((a,b)=>b[1]-a[1]).slice(0,15);horizontalBar("chartHousing",top.map(x=>x[0]),top.map(x=>x[1]),"Viviendas","#7c3aed",false,(i,label)=>selectMunicipalityFromChart(label));const sections=new Map();territory.forEach(r=>{const meaningful=String(r.valor_raw||"").trim()!=="";if(meaningful)sections.set(r.seccion_fuente,(sections.get(r.seccion_fuente)||0)+1);});const arr=[...sections.entries()].sort((a,b)=>b[1]-a[1]);horizontalBar("chartTerritorySections",arr.map(x=>x[0].replace(/^\d+\.\s*/,"")),arr.map(x=>x[1]),"Registros","#64748b",false,(i,label)=>{const raw=arr[i]?.[0];if(raw)setLocalTableFilter("tblTerritory",2,raw,`Sección: ${label}`,true,"chartTerritorySections");});}
function renderNeeds(needs){const counts=new Map();needs.forEach(r=>{if(r.necesidad&&!norm(r.necesidad).startsWith("SIN INFORMACION"))counts.set(r.sector,(counts.get(r.sector)||0)+1);});const arr=[...counts.entries()].sort((a,b)=>b[1]-a[1]);horizontalBar("chartNeeds",arr.map(x=>x[0]),arr.map(x=>x[1]),"Registros","#198754",false,(i,label)=>setLocalTableFilter("tblNeeds",2,label,`Sector: ${label}`,true,"chartNeeds"));}
function renderAnimals(rows){document.getElementById("animalMunicipalities").textContent=fmt(rows.length);document.getElementById("animalTotal").textContent=fmt(sum(rows,"total_animales_cuantificados"));document.getElementById("animalDogs").textContent=fmt(sum(rows,"perros_cuantificados"));document.getElementById("animalCats").textContent=fmt(sum(rows,"gatos_cuantificados"));doughnut("chartAnimals",["Perros","Gatos"],[sum(rows,"perros_cuantificados"),sum(rows,"gatos_cuantificados")],(i,label)=>{const col=label==="Perros"?2:3;setLocalTableRegexFilter("tblAnimals",col,"^(?!0$|Sin dato$|$).+",`${label}: municipios con cantidad reportada`,"chartAnimals");});}
function renderQuality(rows){document.getElementById("qualityTotal").textContent=fmt(rows.length);document.getElementById("qualityHigh").textContent=fmt(rows.filter(r=>norm(r.nivel)==="ALTO").length);document.getElementById("qualityValidation").textContent=fmt(rows.filter(r=>norm(r.clasificacion_accion).includes("VALIDACION")||norm(r.accion_recomendada).includes("VALIDAR")||norm(r.accion_recomendada).includes("VERIFICAR")).length);document.getElementById("qualityImpact").textContent=fmt(rows.filter(r=>norm(r.impacta_indicador).startsWith("SI")).length);const act=new Map();rows.forEach(r=>act.set(r.clasificacion_accion||"SIN CLASIFICAR",(act.get(r.clasificacion_accion||"SIN CLASIFICAR")||0)+1));doughnut("chartQualityActions",[...act.keys()],[...act.values()],(i,label)=>setLocalTableFilter("tblQuality",6,label,`Acción: ${label}`,true,"chartQualityActions"));const lvl=new Map();rows.forEach(r=>lvl.set(r.nivel||"SIN NIVEL",(lvl.get(r.nivel||"SIN NIVEL")||0)+1));horizontalBar("chartQualityLevel",[...lvl.keys()],[...lvl.values()],"Hallazgos","#f59e0b",false,(i,label)=>setLocalTableFilter("tblQuality",4,label,`Nivel: ${label}`,true,"chartQualityLevel"));}
const DT_LANG={search:"Buscar:",lengthMenu:"Mostrar _MENU_",info:"_START_ a _END_ de _TOTAL_",infoEmpty:"Sin registros",zeroRecords:"Sin resultados",paginate:{next:"Siguiente",previous:"Anterior"}};
function renderTable(id,rows,columns,title){if(tables[id]){tables[id].destroy();delete tables[id];}document.querySelectorAll(`[data-filter-table="${id}"]`).forEach(el=>el.classList.remove("selected-filter"));const strip=document.getElementById(`${id}LocalFilter`);strip?.classList.add("d-none");const el=document.getElementById(id);el.innerHTML="";tables[id]=$(el).DataTable({data:rows,columns:columns.map(c=>({title:c})),pageLength:10,order:[],language:DT_LANG,dom:"Bfrtip",buttons:[{extend:"excelHtml5",text:"Excel",title,className:"btn btn-success btn-sm"},{extend:"csvHtml5",text:"CSV",title,className:"btn btn-secondary btn-sm"},{extend:"print",text:"Imprimir",className:"btn btn-outline-primary btn-sm"}]});}
function renderTables(d){renderTable("tblServices",d.services.map(r=>[r.municipio,r.aro_uesvalle,r.servicio,serviceStatus(r),fmt(r.familias_sin_servicio),fmt(r.personas_sin_servicio),r.recuperacion_clasificada||"",r.descripcion_afectacion||""]),["MUNICIPIO","ARO","SERVICIO","ESTADO","FAMILIAS SIN SERVICIO","PERSONAS SIN SERVICIO","RECUPERACIÓN","DESCRIPCIÓN"],"EDAN_SERVICIOS");renderTable("tblContext",d.context.map(r=>[r.municipio,r.aro_uesvalle,yesNo(r.agua_afectada),yesNo(r.salud_afectada),yesNo(r.energia_afectada),yesNo(r.albergue_reportado),yesNo(r.accesibilidad_afectada),fmt(r.numero_alertas_cruzadas),alertDetail(r),healthDetail(r.municipio,d.health||[])]),["MUNICIPIO","ARO","AGUA","SALUD","ENERGÍA","ALBERGUE","ACCESO","ALERTAS","ALERTAS DETALLE","SALUD DETALLE"],"EDAN_CONTEXTO_SANITARIO");renderTable("tblTerritory",d.territory.map(r=>[r.municipio,r.aro_uesvalle,r.seccion_fuente,r.componente,r.indicador,r.valor_raw]),["MUNICIPIO","ARO","SECCIÓN","COMPONENTE","INDICADOR","VALOR"],"EDAN_AFECTACION_TERRITORIAL");renderTable("tblNeeds",d.needs.map(r=>[r.municipio,r.aro_uesvalle,r.sector,r.necesidad,r.equipos_elementos,r.costo_estimado?fmt(r.costo_estimado):"",r.estado_informacion]),["MUNICIPIO","ARO","SECTOR","NECESIDAD","EQUIPOS / ELEMENTOS","COSTO","ESTADO"],"EDAN_NECESIDADES");renderTable("tblAnimals",d.animals.map(r=>[r.municipio,r.aro_uesvalle,fmt(r.perros_cuantificados),fmt(r.gatos_cuantificados),fmt(r.total_animales_cuantificados),yesNo(r.requiere_alimento),yesNo(r.requiere_medicamentos),r.reporte_animales]),["MUNICIPIO","ARO","PERROS","GATOS","TOTAL","ALIMENTO","MEDICAMENTOS","REPORTE"],"EDAN_ANIMALES");renderTable("tblQuality",d.quality.map(r=>[r.municipio,r.columna_fuente,r.tipo_inconsistencia,r.detalle,r.nivel,r.accion_recomendada,r.clasificacion_accion,r.estado,r.impacta_indicador]),["MUNICIPIO","COLUMNA","HALLAZGO","DETALLE","NIVEL","ACCIÓN RECOMENDADA","CLASIFICACIÓN","ESTADO","IMPACTA INDICADOR"],"EDAN_CALIDAD");}
function yesNo(v){return num(v)>0?"Sí":"No";}
function isMarkedState(value){const s=norm(value);return s==="MARCADO"||s==="MARCA X"||s==="X"||s==="SI";}
function serviceInfoClass(r){const s=norm(r?.estado_informacion_afectacion);if(s.includes("PARCIAL")||s.includes("REVISAR"))return"INFORMACIÓN PARCIAL / REVISAR";if(num(r?.afectacion_identificada)>0||s==="AFECTACION REPORTADA"||(s.startsWith("REPORTADO")&&!s.includes("SIN AFECTACION")&&!s.includes("SIN MARCA")))return"AFECTACIÓN REPORTADA";if(s==="SIN AFECTACION REPORTADA"||(s.startsWith("REPORTADO")&&(s.includes("SIN AFECTACION")||s.includes("SIN MARCA"))))return"SIN AFECTACIÓN REPORTADA";return"PENDIENTE / SIN INFORMACIÓN";}
function serviceStatus(r){if(isMarkedState(r.destruido_estado))return"Destruido";if(isMarkedState(r.fuera_servicio_estado))return"Fuera de servicio";if(isMarkedState(r.uso_restringido_estado))return"Uso restringido";if(isMarkedState(r.averiado_estado))return"Averiado";const info=serviceInfoClass(r);if(info==="INFORMACIÓN PARCIAL / REVISAR")return"Requiere revisión";if(info==="PENDIENTE / SIN INFORMACIÓN")return"Sin información";if(info==="SIN AFECTACIÓN REPORTADA")return"Sin afectación reportada";return"Afectación reportada";}
function buildMapStats(munis,services,health,housing,context){MAP_STATS=new Map();munis.forEach(m=>{const key=canonical(m.municipio),w=getService(services,m.municipio,"Acueducto"),e=getService(services,m.municipio,"Energía eléctrica"),h=health.find(r=>canonical(r.municipio)===key),v=housing.find(r=>canonical(r.municipio)===key),c=context.find(r=>canonical(r.municipio)===key);MAP_STATS.set(key,{name:m.municipio,aro:m.aro_uesvalle,personas_afectadas:toNumber(m.personas_afectadas),familias_afectadas:toNumber(m.familias_afectadas),heridos:toNumber(m.heridos),fallecidos:toNumber(m.fallecidos),viviendas_averiadas:v?toNumber(v.total_averiadas):null,personas_sin_agua:w?toNumber(w.personas_sin_servicio):null,personas_sin_energia:e?toNumber(e.personas_sin_servicio):null,salud_afectada:h?num(h.afectacion_salud_identificada):null,albergue:c?num(c.albergue_reportado):null,alertas:c?num(c.numero_alertas_cruzadas):null});});}
function getFeatureMunicipality(p={}){return p.MPIO_CNMBRE||p.MPIO_CNMBR||p.MUNICIPIO||p.NOM_MUN||p.NOMBRE||p.MPIO||p.NAME||"";}
function arcgisGeoJSONQuery(url){const q=new URLSearchParams({where:"1=1",outFields:"*",returnGeometry:"true",outSR:"4326",f:"geojson"});return`${url}/query?${q}`;}
async function fetchLayerGeoJSON(url){const r=await fetch(arcgisGeoJSONQuery(url),{cache:"no-store"});if(!r.ok)throw new Error(`HTTP ${r.status}`);const d=await r.json();if(d.type!=="FeatureCollection")throw new Error("GeoJSON inválido");return d;}
function initMap(){if(MAP)return;MAP=L.map("map",{zoomControl:true,preferCanvas:true}).setView(VALLE_CENTER,VALLE_ZOOM);createPanes();BASEMAPS={cartoLight:L.tileLayer("https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png",{maxZoom:20,attribution:"© OpenStreetMap © CARTO"}),esriTopo:L.tileLayer("https://server.arcgisonline.com/ArcGIS/rest/services/World_Topo_Map/MapServer/tile/{z}/{y}/{x}",{maxZoom:19,attribution:"Esri"}),esriImagery:L.tileLayer("https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}",{maxZoom:19,attribution:"Esri"}),osm:L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:19,attribution:"© OpenStreetMap"})};CURRENT_BASEMAP=BASEMAPS.cartoLight.addTo(MAP);MUNICIPAL_LABELS=L.layerGroup([], {pane:"labelPane"}).addTo(MAP);HOSPITAL_LAYER=L.layerGroup().addTo(MAP);initTerritorialLayers();loadMunicipalPolygons();}
function createPanes(){[["territorialPane",410],["municipalPane",430],["contourPane",450],["labelPane",610]].forEach(([n,z])=>{const p=MAP.getPane(n)||MAP.createPane(n);p.style.zIndex=String(z);if(["territorialPane","contourPane","labelPane"].includes(n))p.style.pointerEvents="none";});}
function initTerritorialLayers(){if(!L.esri?.featureLayer)return;TERRITORIAL_LAYERS={veredas:L.esri.featureLayer({url:LAYER_URLS.veredas,pane:"territorialPane",interactive:false,style:{color:"#c9ced6",weight:.75,fillOpacity:.015}}),centrosPoblados:L.esri.featureLayer({url:LAYER_URLS.centrosPoblados,pane:"territorialPane",interactive:false,pointToLayer:(g,ll)=>L.circleMarker(ll,{pane:"territorialPane",interactive:false,radius:3,color:"#b45309",fillColor:"#f59e0b",fillOpacity:.8,weight:1})}),vias:L.esri.featureLayer({url:LAYER_URLS.vias,pane:"territorialPane",interactive:false,style:{color:"#475569",weight:1.5}}),rios:L.esri.featureLayer({url:LAYER_URLS.rios,pane:"territorialPane",interactive:false,style:{color:"#0ea5e9",weight:1.4}}),valleContorno:L.esri.featureLayer({url:LAYER_URLS.valleContorno,pane:"contourPane",interactive:false,style:{color:"#111827",weight:2.5,fillOpacity:0}}),municipiosUES:L.esri.featureLayer({url:LAYER_URLS.municipiosUES,pane:"contourPane",interactive:false,style:{color:"#0f766e",weight:2,fillOpacity:.03}})};syncLayers();}
async function loadMunicipalPolygons(){try{const geo=await fetchLayerGeoJSON(LAYER_URLS.municipios);MUNICIPAL_LAYER=L.geoJSON(geo,{pane:"municipalPane",style:municipalityStyle,onEachFeature:(f,l)=>bindMunicipality(l,f)}).addTo(MAP);MUNICIPAL_FEATURE_COUNT=MUNICIPAL_LAYER.getLayers().length;VALLE_BOUNDS=MUNICIPAL_LAYER.getBounds();renderMunicipalityLabels();syncLayers();MAP.fitBounds(VALLE_BOUNDS,{padding:[12,12]});refreshMap();}catch(error){console.warn("GeoJSON municipal falló; usando Esri Leaflet",error);MUNICIPAL_LAYER_ERROR=error.message;if(L.esri?.featureLayer){MUNICIPAL_LAYER=L.esri.featureLayer({url:LAYER_URLS.municipios,pane:"municipalPane",simplifyFactor:.25,precision:5,style:f=>municipalityStyle(f)}).addTo(MAP);MUNICIPAL_LAYER.on("createfeature",e=>bindMunicipality(e.layer,e.feature));MUNICIPAL_LAYER.on("load",()=>{MUNICIPAL_FEATURE_COUNT=0;MUNICIPAL_LAYER.eachFeature(()=>MUNICIPAL_FEATURE_COUNT++);try{VALLE_BOUNDS=MUNICIPAL_LAYER.getBounds();}catch(_){}renderMunicipalityLabels();refreshMap();if(VALLE_BOUNDS?.isValid())MAP.fitBounds(VALLE_BOUNDS,{padding:[12,12]});});}}
}
function eachMunicipal(cb){if(!MUNICIPAL_LAYER)return;if(typeof MUNICIPAL_LAYER.eachFeature==="function")MUNICIPAL_LAYER.eachFeature(cb);else MUNICIPAL_LAYER.eachLayer(cb);}
function currentMetric(){return document.querySelector('input[name="mapMetric"]:checked')?.value||"personas_afectadas";}
function metricLabel(){return MAP_METRICS[currentMetric()]?.label||currentMetric();}
function metricValue(stats){return stats?.[currentMetric()]??null;}
function quantiles(){const vals=[...MAP_STATS.values()].map(metricValue).filter(v=>Number.isFinite(v)&&v>0).sort((a,b)=>a-b);if(!vals.length)return[1,2,3,4];const q=p=>vals[Math.min(vals.length-1,Math.max(0,Math.floor((vals.length-1)*p)))];return[q(.2),q(.4),q(.6),q(.8)];}
function colorFor(value){const def=MAP_METRICS[currentMetric()]||{};if(value===null||value===undefined||!Number.isFinite(value))return"#e5e7eb";if(value===0)return"#f8fafc";if(def.type==="binary")return"#dc2626";if(def.type==="alerts")return value>=4?"#991b1b":value>=3?"#dc2626":value>=2?"#f97316":"#fbbf24";const q=quantiles();if(value<=q[0])return MAP_COLORS[0];if(value<=q[1])return MAP_COLORS[1];if(value<=q[2])return MAP_COLORS[2];if(value<=q[3])return MAP_COLORS[3];return MAP_COLORS[4];}
function municipalityStyle(feature){const name=getFeatureMunicipality(feature?.properties),key=canonical(name),s=MAP_STATS.get(key),selected=SELECTED_MUNICIPALITY&&canonical(SELECTED_MUNICIPALITY)===key;return{pane:"municipalPane",color:selected?"#0f172a":"#475569",weight:selected?4:1.2,fillColor:colorFor(metricValue(s)),fillOpacity:s?(selected?.9:.76):.15};}
function popupHTML(name){const key=canonical(name),s=MAP_STATS.get(key);if(!s)return`<div class="popup-edan"><h4>${escapeHTML(name)}</h4><p>Sin coincidencia EDAN en el universo filtrado.</p></div>`;return`<div class="popup-edan"><h4>${escapeHTML(s.name)}</h4><div class="small text-muted mb-2">${escapeHTML(s.aro||"")}</div><div class="popup-grid"><div class="popup-metric"><small>Personas afectadas</small><b>${fmt(s.personas_afectadas)}</b></div><div class="popup-metric"><small>Sin servicio de acueducto</small><b>${fmt(s.personas_sin_agua)}</b></div><div class="popup-metric"><small>Viviendas averiadas</small><b>${fmt(s.viviendas_averiadas)}</b></div><div class="popup-metric"><small>Alertas sanitarias</small><b>${fmt(s.alertas)}</b></div></div><button class="btn btn-primary btn-sm w-100 mt-2" data-open-municipality="${escapeHTML(s.name)}">Abrir ficha</button></div>`;}
function findMunicipalityLayer(name){let found=null;eachMunicipal(layer=>{if(!found&&canonical(getFeatureMunicipality(layer.feature?.properties))===canonical(name))found=layer;});return found;}
function highlightSelected(){eachMunicipal(layer=>layer.setStyle?.(municipalityStyle(layer.feature)));if(!SELECTED_MUNICIPALITY)return;const target=findMunicipalityLayer(SELECTED_MUNICIPALITY);if(target?.getBounds){target.bringToFront?.();const bounds=target.getBounds();if(bounds?.isValid?.())MAP.fitBounds(bounds,{padding:[30,30],maxZoom:11});}}
function selectMunicipality(name,{toggle=false,openDrawer=true,focus=true}={}){const select=document.getElementById("fMunicipality");if(!select||!name)return false;const option=[...select.options].find(o=>canonical(o.value)===canonical(name));if(!option)return false;if(toggle&&canonical(select.value)===canonical(option.value)){select.value="";SELECTED_MUNICIPALITY="";applyFilters();if(focus&&VALLE_BOUNDS?.isValid())MAP?.fitBounds(VALLE_BOUNDS,{padding:[12,12]});return false;}select.value=option.value;SELECTED_MUNICIPALITY=option.value;applyFilters();if(focus)setTimeout(()=>highlightSelected(),80);if(openDrawer)setTimeout(()=>openMunicipalityDrawer(option.value),120);return true;}
function bindMunicipality(layer,feature){const name=getFeatureMunicipality(feature?.properties);layer.bindPopup(popupHTML(name));layer.on("click",()=>{const source=DATA.municipios.find(r=>canonical(r.municipio)===canonical(name));if(source)selectMunicipality(source.municipio,{toggle:false,openDrawer:true,focus:true});});layer.on("popupopen",e=>{setTimeout(()=>{e.popup.getElement()?.querySelector("[data-open-municipality]")?.addEventListener("click",ev=>selectMunicipality(ev.currentTarget.dataset.openMunicipality,{toggle:false,openDrawer:true,focus:true}));},0);});}
function renderMunicipalityLabels(){if(!MUNICIPAL_LABELS)return;MUNICIPAL_LABELS.clearLayers();eachMunicipal(layer=>{const b=layer.getBounds?.();if(!b?.isValid())return;const n=getFeatureMunicipality(layer.feature?.properties);L.marker(b.getCenter(),{interactive:false,pane:"labelPane",icon:L.divIcon({className:"municipio-label",html:`<div>${escapeHTML(n)}</div>`})}).addTo(MUNICIPAL_LABELS);});}
function toggleLayer(layer,visible){if(!MAP||!layer)return;if(visible&&!MAP.hasLayer(layer))layer.addTo(MAP);if(!visible&&MAP.hasLayer(layer))MAP.removeLayer(layer);}
function syncLayers(){toggleLayer(MUNICIPAL_LAYER,document.getElementById("showMunicipalPolygons")?.checked!==false);toggleLayer(MUNICIPAL_LABELS,document.getElementById("showMunicipalityLabels")?.checked!==false);toggleLayer(TERRITORIAL_LAYERS.veredas,document.getElementById("showVeredasValle")?.checked===true);toggleLayer(TERRITORIAL_LAYERS.centrosPoblados,document.getElementById("showCentrosPoblados")?.checked===true);toggleLayer(TERRITORIAL_LAYERS.vias,document.getElementById("showViasPrincipales")?.checked===true);toggleLayer(TERRITORIAL_LAYERS.rios,document.getElementById("showRios")?.checked===true);toggleLayer(TERRITORIAL_LAYERS.valleContorno,document.getElementById("showValleContorno")?.checked===true);toggleLayer(TERRITORIAL_LAYERS.municipiosUES,document.getElementById("showMunicipiosUES")?.checked===true);toggleLayer(HOSPITAL_LAYER,document.getElementById("showHospitals")?.checked!==false);}
