let CURRENT_SERVICES=[];let ACTIVE_SERVICE_VIEW="RESUMEN";
function municipalServiceInfoCounts(municipio){const rows=DATA.servicios.filter(r=>canonical(r.municipio)===canonical(municipio));const counts={reported:0,review:0,pending:0};rows.forEach(r=>{const c=serviceInfoClass(r);if(c==="AFECTACIÓN REPORTADA"||c==="SIN AFECTACIÓN REPORTADA")counts.reported++;else if(c==="INFORMACIÓN PARCIAL / REVISAR")counts.review++;else counts.pending++;});return counts;}
function municipalServiceInfoStatus(municipio){const c=municipalServiceInfoCounts(municipio);if(c.reported>0)return"CON INFORMACIÓN REPORTADA";if(c.review>0)return"INFORMACIÓN PARCIAL / REVISAR";return"PENDIENTE / SIN INFORMACIÓN";}
function municipalServiceInfoCount(municipio){return municipalServiceInfoCounts(municipio).reported;}
function renderInfoTable(munis){const rows=munis.map(m=>{const c=municipalServiceInfoCounts(m.municipio);return[m.municipio,m.aro_uesvalle,municipalServiceInfoStatus(m.municipio),c.reported,c.review,c.pending];});renderTable("tblInfoStatus",rows,["MUNICIPIO","ARO","ESTADO DE INFORMACIÓN","SERVICIOS CON INFORMACIÓN","SERVICIOS EN REVISIÓN","SERVICIOS PENDIENTES"],"EDAN_ESTADO_INFORMACION");const reported=munis.filter(m=>municipalServiceInfoStatus(m.municipio)==="CON INFORMACIÓN REPORTADA").length,review=munis.filter(m=>municipalServiceInfoStatus(m.municipio)==="INFORMACIÓN PARCIAL / REVISAR").length,pending=munis.filter(m=>municipalServiceInfoStatus(m.municipio)==="PENDIENTE / SIN INFORMACIÓN").length;const e=document.getElementById("infoStatusSummary");if(e)e.textContent=`Con información reportada: ${reported} municipio(s) · Información parcial / en revisión: ${review} · Pendientes / sin información: ${pending}.`;}
function setServiceView(service,scroll){ACTIVE_SERVICE_VIEW=service||"RESUMEN";document.querySelectorAll("[data-service-view]").forEach(b=>b.classList.toggle("active",norm(b.dataset.serviceView)===norm(ACTIVE_SERVICE_VIEW)));const summary=document.getElementById("servicesSummaryView"),detail=document.getElementById("serviceDetailView");if(norm(ACTIVE_SERVICE_VIEW)==="RESUMEN"){summary?.classList.remove("d-none");detail?.classList.add("d-none");tables.tblServices?.search("").draw();if(scroll)document.getElementById("servicesTableSection")?.scrollIntoView({behavior:"smooth",block:"start"});return;}summary?.classList.add("d-none");detail?.classList.remove("d-none");renderServiceDetail(ACTIVE_SERVICE_VIEW);if(scroll)setTimeout(()=>document.getElementById("serviceDetailSection")?.scrollIntoView({behavior:"smooth",block:"start"}),100);}
function serviceDetailText(service){const n=norm(service);if(n==="ACUEDUCTO")return"Abastecimiento de agua para consumo humano. Incluye población sin servicio, afectación, recuperación y dependencias críticas.";if(n==="ALCANTARILLADO")return"Componente específico de recolección y evacuación de aguas residuales. Sin información no se interpreta como ausencia de afectación.";if(n==="SANEAMIENTO BASICO")return"Seguimiento del componente de saneamiento básico reportado en el EDAN, conservando la descripción original y su estado de verificación.";if(n==="RECOLECCION DE BASURAS")return"Continuidad del servicio de recolección de residuos sólidos, relevante para condiciones sanitarias en zonas afectadas y albergues.";if(n==="ENERGIA ELECTRICA")return"Servicio esencial relacionado y variable crítica para bombeo, PTAP, establecimientos de salud y albergues.";if(n==="GAS")return"Afectaciones reportadas al servicio de gas dentro de la sección de servicios públicos esenciales.";return"Detalle municipal del servicio seleccionado.";}
function renderServiceDetail(service){const rows=CURRENT_SERVICES.filter(r=>norm(r.servicio)===norm(service));const affected=rows.filter(r=>serviceInfoClass(r)==="AFECTACIÓN REPORTADA"),pending=rows.filter(r=>serviceInfoClass(r)==="PENDIENTE / SIN INFORMACIÓN");document.getElementById("serviceDetailTitle").textContent=service;document.getElementById("serviceDetailIntro").textContent=serviceDetailText(service);document.getElementById("serviceTableTitle").textContent=`Detalle municipal · ${service}`;document.getElementById("svcAffected").textContent=fmt(affected.length);document.getElementById("svcFamilies").textContent=fmt(sum(rows,"familias_sin_servicio"));document.getElementById("svcPeople").textContent=fmt(sum(rows,"personas_sin_servicio"));document.getElementById("svcPending").textContent=fmt(pending.length);document.getElementById("svcOut").textContent=fmt(rows.filter(r=>isMarkedState(r.fuera_servicio_estado)).length);const cats=["AFECTACIÓN REPORTADA","SIN AFECTACIÓN REPORTADA","INFORMACIÓN PARCIAL / REVISAR","PENDIENTE / SIN INFORMACIÓN"],vals=cats.map(c=>rows.filter(r=>serviceInfoClass(r)===c).length);doughnut("chartServiceStatus",cats,vals,(i,label)=>setLocalTableFilter("tblServiceDetail",3,label,`${service} · ${label}`,true,"chartServiceStatus"),["#dc2626","#16a34a","#f59e0b","#94a3b8"]);const rec=new Map();rows.filter(r=>r.recuperacion_clasificada&&norm(r.recuperacion_clasificada)!=="SIN DATO").forEach(r=>rec.set(r.recuperacion_clasificada,(rec.get(r.recuperacion_clasificada)||0)+1));doughnut("chartServiceRecovery",[...rec.keys()],[...rec.values()],(i,label)=>setLocalTableFilter("tblServiceDetail",6,label,`${service} · recuperación: ${label}`,true,"chartServiceRecovery"));renderTable("tblServiceDetail",rows.map(r=>[r.municipio,r.aro_uesvalle,serviceStatus(r),serviceInfoClass(r),fmt(r.familias_sin_servicio),fmt(r.personas_sin_servicio),r.recuperacion_clasificada||"",r.descripcion_afectacion||"",r.perspectiva_recuperacion||""]),["MUNICIPIO","ARO","ESTADO","ESTADO DE INFORMACIÓN","FAMILIAS SIN SERVICIO","PERSONAS SIN SERVICIO","RECUPERACIÓN","DESCRIPCIÓN","PERSPECTIVA DE RECUPERACIÓN"],`EDAN_${norm(service).replace(/ /g,"_")}`);}
function renderShelters(rows){document.getElementById("shelterMunicipalities").textContent=fmt(rows.length);document.getElementById("shelterFamilies").textContent=fmt(sum(rows,"familias_cuantificadas"));document.getElementById("shelterPeople").textContent=fmt(sum(rows,"personas_cuantificadas"));document.getElementById("shelterWater").textContent=fmt(rows.filter(r=>!norm(r.agua_condicion).includes("SIN DATO")&&!norm(r.agua_condicion).includes("DISPONIBLE")).length);document.getElementById("shelterSanitation").textContent=fmt(rows.filter(r=>!norm(r.saneamiento_condicion).includes("DISPONIBLE")).length);document.getElementById("shelterEnergy").textContent=fmt(rows.filter(r=>norm(r.energia_condicion).includes("AFECTADA")||norm(r.energia_condicion).includes("AFECTACION")).length);const wc=new Map(),sc=new Map(),ec=new Map();rows.forEach(r=>{wc.set(r.agua_condicion||"SIN DATO",(wc.get(r.agua_condicion||"SIN DATO")||0)+1);sc.set(r.saneamiento_condicion||"SIN DATO",(sc.get(r.saneamiento_condicion||"SIN DATO")||0)+1);ec.set(r.energia_condicion||"SIN DATO",(ec.get(r.energia_condicion||"SIN DATO")||0)+1);});doughnut("chartShelterWater",[...wc.keys()],[...wc.values()],(i,label)=>setLocalTableFilter("tblShelters",4,label,`Albergues · agua: ${label}`,true,"chartShelterWater"));doughnut("chartShelterSanitation",[...sc.keys()],[...sc.values()],(i,label)=>setLocalTableFilter("tblShelters",6,label,`Albergues · saneamiento: ${label}`,true,"chartShelterSanitation"));doughnut("chartShelterEnergy",[...ec.keys()],[...ec.values()],(i,label)=>setLocalTableFilter("tblShelters",5,label,`Albergues · energía: ${label}`,true,"chartShelterEnergy"));renderTable("tblShelters",rows.map(r=>[r.municipio,r.aro_uesvalle,fmt(r.familias_cuantificadas),fmt(r.personas_cuantificadas),r.agua_condicion,r.energia_condicion,r.saneamiento_condicion,r.estado_cuantificacion,r.detalle_reportado,r.necesidades_relevantes]),["MUNICIPIO","ARO","FAMILIAS CUANTIFICADAS","PERSONAS CUANTIFICADAS","AGUA","ENERGÍA","SANEAMIENTO","CUANTIFICACIÓN","DETALLE REPORTADO","NECESIDADES"],"EDAN_ALBERGUES_REFUGIOS");}

function pdfMetric(doc,x,y,w,label,value){doc.setFillColor(245,248,252);doc.roundedRect(x,y,w,17,2,2,"F");doc.setFont("helvetica","bold");doc.setFontSize(13);doc.setTextColor(29,78,216);doc.text(String(value),x+w/2,y+7,{align:"center"});doc.setFont("helvetica","normal");doc.setFontSize(7);doc.setTextColor(71,84,103);doc.text(doc.splitTextToSize(label,w-4),x+w/2,y+12,{align:"center"});}
function pdfHeader(doc,title,subtitle){doc.setFillColor(46,100,210);doc.rect(0,0,210,13,"F");doc.setTextColor(255,255,255);doc.setFont("helvetica","bold");doc.setFontSize(12);doc.text("UESVALLE · EDAN",12,8.5);doc.setTextColor(15,23,42);doc.setFontSize(18);doc.text(title,12,25);doc.setFont("helvetica","normal");doc.setFontSize(9);doc.setTextColor(71,84,103);doc.text(doc.splitTextToSize(subtitle,185),12,31);}
function pdfFooter(doc){const pages=doc.getNumberOfPages();for(let i=1;i<=pages;i++){doc.setPage(i);doc.setFontSize(7);doc.setTextColor(100,116,139);doc.text("Fuente: matriz EDAN procesada por UESVALLE + Paquete Hospitales Terremoto Valle 2026 V1. Cifras sujetas a actualización.",12,287);doc.text(`${i}/${pages}`,198,287,{align:"right"});}}
function pdfMapDataUrl(){try{const features=[];eachMunicipal(layer=>{const g=layer.feature?.geometry;if(g)features.push({g,style:municipalityStyle(layer.feature),name:getFeatureMunicipality(layer.feature?.properties)});});if(!features.length)return null;const coords=[];function collect(a){if(typeof a?.[0]==="number"&&typeof a?.[1]==="number")coords.push(a);else if(Array.isArray(a))a.forEach(collect);}features.forEach(f=>collect(f.g.coordinates));if(!coords.length)return null;const minX=Math.min(...coords.map(c=>c[0])),maxX=Math.max(...coords.map(c=>c[0])),minY=Math.min(...coords.map(c=>c[1])),maxY=Math.max(...coords.map(c=>c[1]));const c=document.createElement("canvas");c.width=900;c.height=600;const ctx=c.getContext("2d");ctx.fillStyle="#ffffff";ctx.fillRect(0,0,c.width,c.height);const pad=22,sx=(c.width-2*pad)/(maxX-minX),sy=(c.height-2*pad)/(maxY-minY),scale=Math.min(sx,sy);function p(x,y){return[pad+(x-minX)*scale,c.height-pad-(y-minY)*scale];}function drawRing(r){r.forEach((xy,i)=>{const [x,y]=p(xy[0],xy[1]);if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);});ctx.closePath();}features.forEach(f=>{ctx.beginPath();if(f.g.type==="Polygon")f.g.coordinates.forEach(drawRing);else if(f.g.type==="MultiPolygon")f.g.coordinates.forEach(poly=>poly.forEach(drawRing));ctx.fillStyle=f.style.fillColor||"#e5e7eb";ctx.fill();ctx.strokeStyle="#475569";ctx.lineWidth=1;ctx.stroke();});if(document.getElementById("showHospitals")?.checked!==false){CURRENT_HOSPITALS.forEach(h=>{const lat=toNumber(h.latitud),lon=toNumber(h.longitud);if(lat===null||lon===null)return;const [x,y]=p(lon,lat);ctx.beginPath();ctx.arc(x,y,5,0,Math.PI*2);ctx.fillStyle=hospitalColor(h.nivel_afectacion);ctx.fill();ctx.strokeStyle="#fff";ctx.lineWidth=1.5;ctx.stroke();});}return c.toDataURL("image/png");}catch(e){console.warn("No fue posible crear mapa PDF",e);return null;}}
function generateBalancePdf(){const jspdf=window.jspdf;if(!jspdf?.jsPDF){alert("No fue posible cargar el generador PDF. Verifique la conexión a internet y vuelva a intentar.");return;}const btn=document.getElementById("btnGeneratePdf");btn?.classList.add("pdf-generating");try{const f=filters(),munis=municipalUniverse(f),keys=new Set(munis.map(r=>canonical(r.municipio))),services=rowsInUniverse(DATA.servicios,keys),health=rowsInUniverse(DATA.salud,keys),housing=rowsInUniverse(DATA.vivienda,keys),context=rowsInUniverse(DATA.contexto,keys),shelters=rowsInUniverse(DATA.albergues,keys),needs=rowsInUniverse(DATA.necesidades,keys),hospitals=rowsInUniverse(DATA.hospitales,keys);const water=services.filter(r=>norm(r.servicio)==="ACUEDUCTO"),energy=services.filter(r=>norm(r.servicio)==="ENERGIA ELECTRICA");const doc=new jspdf.jsPDF({unit:"mm",format:"a4"}),municipal=Boolean(f.municipality),title=municipal?`Balance municipal · ${f.municipality}`:"Balance departamental de afectaciones",cut=DATA.metadata?.fecha_evento||DATA.metadata?.procesado_en||"11/08/2026";pdfHeader(doc,title,`Evento sísmico · Valle del Cauca · Corte de información: ${cut}. Reporte informativo generado desde el tablero EDAN UESVALLE.`);let y=42;const metrics=[["Municipios analizados",fmt(munis.length)],["Personas afectadas",fmt(sum(munis,"personas_afectadas"))],["Heridos",fmt(sum(munis,"heridos"))],["Fallecidos",fmt(sum(munis,"fallecidos"))],["Personas sin servicio de acueducto",fmt(sum(water,"personas_sin_servicio"))],["Personas sin energía",fmt(sum(energy,"personas_sin_servicio"))],["Viviendas averiadas",fmt(sum(housing,"total_averiadas"))],["Municipios con alertas",fmt(context.filter(r=>num(r.numero_alertas_cruzadas)>0).length)]];metrics.forEach((m,i)=>pdfMetric(doc,12+(i%4)*47, y+Math.floor(i/4)*21,44,m[0],m[1]));y+=47;doc.setFont("helvetica","bold");doc.setFontSize(11);doc.setTextColor(15,23,42);doc.text("Lectura general",12,y);doc.setFont("helvetica","normal");doc.setFontSize(8.5);doc.setTextColor(51,65,85);const narrative=`El corte analiza ${fmt(munis.length)} municipio(s). Se reportan ${fmt(sum(munis,"personas_afectadas"))} personas afectadas y ${fmt(sum(water,"personas_sin_servicio"))} personas sin servicio de acueducto. Las alertas cruzadas UESVALLE identifican coincidencias territoriales de agua con salud, energía, acceso o albergues y no sustituyen la valoración EDAN original.`;doc.text(doc.splitTextToSize(narrative,185),12,y+6);y+=22;const map=pdfMapDataUrl();if(map){doc.addImage(map,"PNG",12,y,90,60);doc.setFontSize(7);doc.setTextColor(100,116,139);doc.text(`Mapa analítico: ${metricLabel()} · puntos = hospitales principales`,12,y+64);}const svcNames=["Acueducto","Alcantarillado","Saneamiento básico","Recolección de basuras","Energía eléctrica","Gas"],svcRows=svcNames.map(s=>[s,services.filter(r=>norm(r.servicio)===norm(s)&&num(r.afectacion_identificada)>0).length,fmt(sum(services.filter(r=>norm(r.servicio)===norm(s)),"personas_sin_servicio"))]);doc.autoTable({startY:y,margin:{left:108,right:12},head:[["Servicio","Municipios afectados","Personas sin servicio"]],body:svcRows,styles:{fontSize:7,cellPadding:1.5},headStyles:{fillColor:[46,100,210]},theme:"grid"});
 doc.addPage();pdfHeader(doc,"Situación sanitaria y capacidad de respuesta",municipal?`Detalle correspondiente a ${f.municipality}.`:`Integración EDAN + red hospitalaria principal.`);const hrows=hospitals.filter(r=>hospitalPct(r)!==null).sort((a,b)=>(hospitalPct(b)||0)-(hospitalPct(a)||0));doc.setFontSize(10);doc.setFont("helvetica","bold");doc.setTextColor(15,23,42);doc.text("Red hospitalaria",12,42);doc.setFont("helvetica","normal");doc.setFontSize(8);doc.text(`Hospitales principales: ${fmt(hospitals.length)} · con afectación >0 %: ${fmt(hospitals.filter(r=>(hospitalPct(r)||0)>0).length)} · ≥50 %: ${fmt(hospitals.filter(r=>(hospitalPct(r)||0)>=50).length)} · críticos/colapso ≥70 %: ${fmt(hospitals.filter(r=>(hospitalPct(r)||0)>=70).length)}.`,12,48);doc.autoTable({startY:53,head:[["Municipio","Hospital","Afectación","Nivel"]],body:hrows.slice(0,12).map(r=>[r.municipio,r.institucion,hospitalPct(r)===null?"—":fmtPct(r.afectacion_pct),r.nivel_afectacion]),styles:{fontSize:7,cellPadding:1.5},headStyles:{fillColor:[220,38,38]},columnStyles:{1:{cellWidth:80}},theme:"grid"});let yy=doc.lastAutoTable.finalY+8;doc.setFont("helvetica","bold");doc.setFontSize(10);doc.text("Alertas analíticas UESVALLE",12,yy);const alerts=[["Agua + salud","alerta_agua_salud"],["Agua + albergue","alerta_agua_albergue"],["Agua + energía","alerta_agua_energia"],["Agua + acceso","alerta_agua_acceso"],["Albergue + energía","alerta_albergue_energia"]];doc.autoTable({startY:yy+4,head:[["Coincidencia territorial","Municipios"]],body:alerts.map(a=>[a[0],countTrue(context,a[1])]),styles:{fontSize:8},headStyles:{fillColor:[15,118,110]},theme:"grid"});
 doc.addPage();pdfHeader(doc,"Respuesta territorial y necesidades",municipal?`Albergues, necesidades y respuesta reportada para ${f.municipality}.`:`Albergues/refugios y principales necesidades del universo departamental.`);doc.setFont("helvetica","bold");doc.setFontSize(10);doc.text("Albergues y refugios",12,42);doc.setFont("helvetica","normal");doc.setFontSize(8);doc.text(`Municipios con reporte: ${fmt(shelters.length)} · familias explícitamente cuantificadas: ${fmt(sum(shelters,"familias_cuantificadas"))} · personas cuantificadas: ${fmt(sum(shelters,"personas_cuantificadas"))}.`,12,48);doc.autoTable({startY:53,head:[["Municipio","Agua","Saneamiento","Energía"]],body:shelters.map(r=>[r.municipio,r.agua_condicion,r.saneamiento_condicion,r.energia_condicion]),styles:{fontSize:6.8,cellPadding:1.3},headStyles:{fillColor:[25,135,84]},theme:"grid"});const nmap=new Map();needs.forEach(r=>{if(r.necesidad&&!norm(r.necesidad).startsWith("SIN INFORMACION"))nmap.set(r.sector,(nmap.get(r.sector)||0)+1);});const nrows=[...nmap.entries()].sort((a,b)=>b[1]-a[1]);yy=Math.min(220,(doc.lastAutoTable?.finalY||53)+8);if(yy>205){doc.addPage();pdfHeader(doc,"Principales necesidades reportadas","Clasificación por sector, conservando la narrativa original en el tablero.");yy=42;}doc.setFont("helvetica","bold");doc.setFontSize(10);doc.text("Necesidades reportadas por sector",12,yy);doc.autoTable({startY:yy+4,head:[["Sector","Registros"]],body:nrows,styles:{fontSize:8},headStyles:{fillColor:[46,100,210]},theme:"grid"});pdfFooter(doc);const safe=(f.municipality||"Valle_del_Cauca").normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^A-Za-z0-9]+/g,"_");doc.save(`EDAN_Balance_${safe}_${String(cut).replace(/[^0-9]/g,"")||"20260811"}.pdf`);}catch(e){console.error(e);alert(`No fue posible generar el PDF: ${e.message||e}`);}finally{btn?.classList.remove("pdf-generating");}}

function resetMapView(){if(VALLE_BOUNDS?.isValid())MAP?.fitBounds(VALLE_BOUNDS,{padding:[12,12]});else MAP?.setView(VALLE_CENTER,VALLE_ZOOM);}function clearFilters({resetView=true}={}){document.getElementById("fMunicipality").value="";document.getElementById("fAro").value="";document.getElementById("fInfo").value="";SELECTED_MUNICIPALITY="";applyFilters();if(resetView)resetMapView();}
function bindEvents(){document.getElementById("btnToggleStatus")?.addEventListener("click",()=>{const box=document.getElementById("loadAlert");if(!box)return;const hidden=box.classList.toggle("d-none");const btn=document.getElementById("btnToggleStatus");const hint=document.getElementById("statusHint");if(btn)btn.textContent=hidden?"Ver detalle":"Ocultar detalle";if(hint)hint.textContent=hidden?"Oculto":"Visible";});document.getElementById("btnGeneratePdf")?.addEventListener("click",generateBalancePdf);document.getElementById("showHospitals")?.addEventListener("change",renderMapLegend);document.getElementById("btnApply")?.addEventListener("click",applyFilters);document.getElementById("btnClear")?.addEventListener("click",()=>clearFilters());document.getElementById("btnClearActiveFilters")?.addEventListener("click",()=>clearFilters());document.getElementById("btnReload")?.addEventListener("click",()=>loadData().catch(showError));document.querySelectorAll('input[name="mapMetric"]').forEach(x=>x.addEventListener("change",refreshMap));document.querySelectorAll('input[name="edanBasemap"]').forEach(x=>x.addEventListener("change",()=>setBasemap(x.value)));["showMunicipalPolygons","showMunicipalityLabels","showVeredasValle","showCentrosPoblados","showViasPrincipales","showRios","showValleContorno","showMunicipiosUES","showHospitals"].forEach(id=>document.getElementById(id)?.addEventListener("change",syncLayers));document.getElementById("btnMapReset")?.addEventListener("click",resetMapView);document.getElementById("btnMapClearFilters")?.addEventListener("click",()=>clearFilters());document.getElementById("btnOpenSelected")?.addEventListener("click",()=>{const m=document.getElementById("fMunicipality").value||SELECTED_MUNICIPALITY;if(m)openMunicipalityDrawer(m);});document.getElementById("fMunicipality")?.addEventListener("change",event=>{const value=event.target.value||"";if(value)selectMunicipality(value,{toggle:false,openDrawer:true,focus:true});else{SELECTED_MUNICIPALITY="";applyFilters();}});["fAro","fInfo"].forEach(id=>document.getElementById(id)?.addEventListener("change",applyFilters));document.querySelectorAll("[data-service-view]").forEach(b=>b.addEventListener("click",()=>setServiceView(b.dataset.serviceView,false)));document.getElementById("btnServiceBack")?.addEventListener("click",()=>setServiceView("RESUMEN",false));document.getElementById("btnSheltersMap")?.addEventListener("click",()=>{const tab=document.querySelector('[data-bs-target="#summary-pane"]');bootstrap.Tab.getOrCreateInstance(tab).show();const radio=document.querySelector('input[name="mapMetric"][value="albergue"]');if(radio)radio.checked=true;setTimeout(()=>{refreshMap();document.getElementById("map")?.scrollIntoView({behavior:"smooth",block:"center"});},180);});document.querySelectorAll('#dashboardTabs button[data-bs-toggle="tab"]').forEach(b=>b.addEventListener("shown.bs.tab",()=>setTimeout(()=>{Object.values(charts).forEach(c=>c.resize?.());Object.values(tables).forEach(t=>t.columns?.adjust());MAP?.invalidateSize();},150)));}
document.addEventListener("DOMContentLoaded",()=>{bindEvents();initAccess();});
